namespace Loupedeck.OBSStudioForLogiPlugin.Tests;

using System.IO;
using System.Linq;
using System.Text.RegularExpressions;

/// <summary>
/// Every action needs an action symbol: the black glyph the Options+ and Loupedeck action picker
/// shows next to its name. Without one the picker shows a generic symbol. Symbols live in
/// src/package/actionsymbols/, named after the action class's full name, and are generated by
/// tools/icons/generate_icons.py (SYMBOLS).
/// </summary>
public class ActionSymbolTests
{
    private const String SymbolPrefix = "Loupedeck.OBSStudioForLogiPlugin.";

    // The SDK base classes that make a class an action the picker lists.
    private static readonly String[] ActionBaseTypes =
    {
        "Loupedeck.PluginDynamicCommand",
        "Loupedeck.PluginMultistateDynamicCommand",
        "Loupedeck.PluginDynamicFolder",
        "Loupedeck.PluginDynamicAdjustment",
        "Loupedeck.ActionEditorCommand",
    };

    private static String SymbolsDirectory()
    {
        DirectoryInfo? directory = new DirectoryInfo(AppContext.BaseDirectory);
        while (directory != null && !File.Exists(Path.Combine(directory.FullName, "OBSStudioForLogiPlugin.sln")))
        {
            directory = directory.Parent;
        }

        Assert.NotNull(directory);
        return Path.Combine(directory!.FullName, "src", "package", "actionsymbols");
    }

    private static Boolean IsAction(Type type)
    {
        for (Type? current = type.BaseType; current != null; current = current.BaseType)
        {
            if (current.FullName != null && ActionBaseTypes.Contains(current.FullName))
            {
                return true;
            }
        }

        return false;
    }

    private static String[] ActionClassNames()
    {
        return typeof(OBSStudioForLogiPlugin).Assembly.GetTypes()
            .Where(type => type.IsClass && !type.IsAbstract && IsAction(type))
            .Select(type => type.FullName!)
            .OrderBy(name => name)
            .ToArray();
    }

    private static String[] SymbolFiles()
    {
        return Directory.GetFiles(SymbolsDirectory(), "*.svg").Select(file => Path.GetFileName(file)).OrderBy(name => name).ToArray();
    }

    [Fact]
    public void ActionClasses_AreFound()
    {
        // Guards the reflection above: if it found nothing, the tests below would pass vacuously.
        Assert.True(ActionClassNames().Length > 40, $"Found only {ActionClassNames().Length} action classes");
    }

    [Fact]
    public void EveryActionClass_HasASymbol()
    {
        String[] symbols = SymbolFiles();

        String[] missing = ActionClassNames().Where(name => !symbols.Contains(name + ".svg")).ToArray();

        Assert.True(missing.Length == 0, "No action symbol for: " + String.Join(", ", missing) + ". Add the class to SYMBOLS in tools/icons/generate_icons.py and run it.");
    }

    [Fact]
    public void EverySymbol_BelongsToAnActionClass()
    {
        String[] actions = ActionClassNames();

        String[] stray = SymbolFiles().Where(file => !actions.Contains(Path.GetFileNameWithoutExtension(file))).ToArray();

        Assert.True(stray.Length == 0, "Action symbols with no matching action class: " + String.Join(", ", stray));
    }

    // The SDK's rules: SVG, single colour (black) strokes and fills, transparent background.
    [Fact]
    public void EverySymbol_IsBlackOnTransparent()
    {
        foreach (String file in Directory.GetFiles(SymbolsDirectory(), "*.svg"))
        {
            String svg = File.ReadAllText(file);
            String name = Path.GetFileName(file);

            Assert.StartsWith(SymbolPrefix, name);
            Assert.Contains("viewBox=\"0 0 32 32\"", svg);
            Assert.Contains("<path", svg);
            Assert.DoesNotContain("<rect", svg);
            Assert.DoesNotContain("<image", svg);

            String[] colours = Regex.Matches(svg, "#[0-9A-Fa-f]{3,8}\\b").Select(match => match.Value.ToUpperInvariant()).Distinct().ToArray();
            Assert.True(colours.SequenceEqual(new[] { "#000000" }), $"{name} uses colours {String.Join(", ", colours)}; symbols must be black only");
        }
    }
}
